"""When to close (section 7), the accept ladder (R12.11) and the close guards of DualAgent and
TeamAgent (R11.17-R11.18, R12.12-R12.13, R12.15, R13.13). Pure functions over `View`s - one per live
supplier thread - so the rules are testable on recorded negotiations without the arena.

Accept the cheapest sheet that keeps the must-haves and beats the alternative when the supplier
agreed (R7.1), made a final offer (R7.2), its offer meets our next target - unless it is still
moving with more than 3 rounds left (R7.3) - its offer is as good as what we last offered (R7.4), at
most one round is left (R7.5), or the planned rounds are over (R7.6). Walk away only when nothing on
the table is acceptable and every thread is at a final offer or out of rounds. No deadlock close and
no walk-risk close.
"""

from dataclasses import dataclass, field

EARLIER_SHARE = 0.001  # R12.11: earlier IDs cheaper by 0.1 %+ go before the latest ones
MAX_EARLIER = 3
REVISIT_SHARE = 0.003  # R12.13: an earlier sheet 0.3 % cheaper is offered back once
COVERAGE_SHARE = 0.01  # R11.17: uncovered need over 1 % of C never "meets our target"
TARGET_TOL = 0.002  # R7.3
LAST_TOL = 0.001  # R7.4
MOVING_ROUNDS = 3  # R5.4 / R7.3
HOPELESS_SHARE, HOPELESS_MOVE = 0.08, 0.01  # R12.15
DEAR_SHARE = 0.25  # R8.2
STALL_TOL = 0.001


@dataclass
class Row:
    """One sheet the supplier put on the table: a main sheet or an alternative."""

    id: str
    terms: dict
    c: float  # our C with the margin charge where the goal has one
    valid: bool  # keeps the must-haves and beats the alternative
    latest: bool  # in its latest e-mail
    main: bool = True
    reply: int = 0  # which of its replies (0 = the opening)
    uncovered: float = 0.0  # EUR of uncovered need (and its risk) in C


@dataclass
class View:
    """One live supplier thread, as the close rules see it."""

    sid: str
    status: str | None
    left: int  # messages we may still send
    sent: int  # our messages that reached it
    rows: list = field(default_factory=list)
    target: float | None = None  # our next target C
    last_target: float | None = None  # the target of our last offer
    moving: bool = False  # still conceding more than 0.4 % of C (R5.4)
    only_price: bool = False  # every step term settled (R13.13)
    planned_over: bool = False  # H + 2 offers made (R7.6)
    close_gap: float = 0.005
    replies_c: list = field(default_factory=list)  # C of its best sheet per reply, oldest first
    earlier_used: bool = False  # R12.13 offer-back already made
    repair_used: bool = False  # R12.12 repair already made
    restore_used: bool = False  # R11.17 coverage message already made
    last_step_share: float = 0.0  # how far it moved in its last reply, share of C

    @property
    def latest_rows(self):
        return [r for r in self.rows if r.latest]

    @property
    def best(self):
        """Its cheapest valid sheet of the latest e-mail (R3.1), else None."""
        ok = [r for r in self.latest_rows if r.valid]
        return min(ok, key=lambda r: r.c) if ok else None

    @property
    def c_now(self):
        rows = self.latest_rows
        return min((r.c for r in rows if r.valid), default=min((r.c for r in rows), default=float("inf")))


@dataclass
class Close:
    kind: str  # accept | walk | idle | offer_back | repair | restore
    reason: str
    sid: str | None = None
    sheet_id: str | None = None
    candidates: list = field(default_factory=list)  # the accept ladder [(sid, sheet_id)]
    terms: dict | None = None  # offer_back / repair / restore: the terms to send


def blocked(views, row, sid):
    """R11.18: never accept a bidder's unchanged opening while a cheaper rival sheet is on the table."""
    if row.reply != 0 or len(views) < 2:
        return False
    return any(r.valid and r.latest and r.c < row.c for v in views.values() if v.sid != sid for r in v.rows)


def ladder(views):
    """R12.11: every valid sheet ever offered in every live thread, cheapest first; up to MAX_EARLIER
    earlier IDs (cheaper by EARLIER_SHARE+) before the latest ones. A refused accept changes nothing."""
    rows = sorted(
        (r.c, not r.latest, not r.main, v.sid, r.id)
        for v in views.values()
        for r in v.rows
        if r.valid and not blocked(views, r, v.sid)
    )
    now = [x for x in rows if not x[1]]
    if not now:
        return []
    earlier = [x for x in rows if x[1] and x[0] < now[0][0] * (1 - EARLIER_SHARE)][:MAX_EARLIER]
    return list(dict.fromkeys((x[3], x[4]) for x in sorted(earlier + now)))


def accept(views, reason):
    cands = ladder(views)
    if not cands:
        return None
    return Close("accept", reason, cands[0][0], cands[0][1], cands)


def walk(views, reason):
    sid = next(iter(views)) if views else None
    return Close("walk", reason, sid)


def earlier_cheaper(view):
    """R12.13: once per thread, an earlier valid sheet of its own 0.3 % cheaper than the best of its
    latest e-mail - its terms go back as our sheet."""
    if view.earlier_used or view.left <= 0 or view.status == "final_offer":
        return None
    now = [r.c for r in view.latest_rows if r.valid] or [r.c for r in view.latest_rows]
    before = [r for r in view.rows if not r.latest and r.valid]
    if not now or not before:
        return None
    r = min(before, key=lambda r: r.c)
    return r if r.c <= (1 - REVISIT_SHARE) * min(now) else None


def stalled(view):
    """No cheaper offer over its last three replies after 3+ of our messages (R12.13)."""
    cs = view.replies_c
    if view.sent < 3 or len(cs) < 3:
        return False
    return cs[-1] >= cs[-3] - max(1.0, STALL_TOL * cs[-3])


def covered(view, row):
    return row is not None and row.uncovered <= COVERAGE_SHARE * row.c


def ends(view):
    """At a final offer or out of rounds: nothing more will come from this thread."""
    return view.status in ("final_offer", "agreed") or view.left <= 0


def hopeless(views, view):
    """R12.15 / R8.2 (RFQ, 3+ live bidders): far dearer than the best and not moving - stop writing."""
    if len(views) < 3 or view.best is None:
        return False
    best_all = min((v.best.c for v in views.values() if v.best), default=None)
    if best_all is None:
        return False
    if (
        view.best.c > (1 + HOPELESS_SHARE) * best_all
        and view.last_step_share < HOPELESS_MOVE
        and len(view.replies_c) >= 3
    ):
        return True
    return view.best.c > (1 + DEAR_SHARE) * best_all and view.sent >= 2


def decide(views, sid, must_close=False):
    """The close rule for thread `sid`, or None (negotiate on). `views`: every live thread."""
    v = views[sid]
    rfq = len(views) > 1
    cands = ladder(views)
    best_sid = cands[0][0] if cands else None
    heard = all(x.sent >= 1 for x in views.values())  # R11.18: every bidder has had an offer
    may_accept = bool(cands) and (not rfq or heard)

    if must_close:  # R11.14: closed by the clock
        return accept(views, "case clock: close") or walk(views, "case clock: nothing acceptable")

    if v.status == "final_offer":  # R12.12: its last word - accept at once, anything more makes it walk
        if cands and (not rfq or best_sid == sid or all(ends(x) for x in views.values())):
            return accept(views, "final offer")
        if cands and rfq:
            return Close("idle", "final offer, a rival is better", sid)
        if not v.repair_used and v.left > 0 and v.rows:
            return Close("repair", "final offer breaks a must-have or loses to the alternative - one repair", sid)
        if all(ends(x) for x in views.values()):
            return walk(views, "nothing acceptable, every thread at its end")
        return Close("idle", "final offer, nothing acceptable here", sid)

    if v.status == "agreed":  # R7.1, R12.13
        if (r := earlier_cheaper(v)) is not None:
            return Close("offer_back", "its earlier offer was cheaper than the agreed sheet", sid, r.id, terms=r.terms)
        if may_accept and (not rfq or best_sid == sid):
            return accept(views, "agreed to our terms")

    if stalled(v):  # R12.13: back to its earlier, cheaper offer once - never a deadlock close (R5.3, R7)
        if (r := earlier_cheaper(v)) is not None:
            return Close("offer_back", "stalled: back to its own earlier, cheaper offer", sid, r.id, terms=r.terms)

    best = v.best
    if best is not None and v.sent >= 1 and v.target is not None:
        meets = best.c <= v.target * (1 + TARGET_TOL) and not (v.moving and v.left > MOVING_ROUNDS)
        if meets and not covered(v, best):  # R11.17
            if v.left > 0 and not v.restore_used:
                return Close("restore", "meets the target but leaves need uncovered", sid, best.id, terms=best.terms)
            meets = False
        if meets and may_accept and best_sid == sid:
            return accept(views, "its offer meets our next target")
        if (
            v.only_price
            and best.c <= v.target * (1 + v.close_gap)
            and covered(v, best)
            and may_accept
            and best_sid == sid
        ):
            return accept(views, "small gap, only price left")  # R13.13
    if best is not None and v.last_target is not None and best.c <= v.last_target * (1 + LAST_TOL):
        if covered(v, best) and may_accept and best_sid == sid:
            return accept(views, "its offer is as good as what we last offered")  # R7.4

    if (v.left <= 1 and not rfq) or all(x.left <= 1 for x in views.values()):  # R7.5
        if may_accept or (cands and rfq):
            return accept(views, "at most one round left")
        if all(ends(x) for x in views.values()):
            return walk(views, "nothing acceptable and no rounds left")
    if all(x.planned_over for x in views.values()) and may_accept:  # R7.6
        return accept(views, "the planned rounds are over")
    if rfq and hopeless(views, v):
        return Close("idle", "far dearer than the best bidder and not moving", sid)
    if v.left <= 0:
        return (
            Close("idle", "no messages left in this thread", sid)
            if rfq
            else (accept(views, "no messages left") or walk(views, "no messages left, nothing acceptable"))
        )
    return None
"""Concessions: reciprocal, never stuck (section 5), with TeamAgent's step size (R12.5).

Everything is in C. Per thread a `Plan` keeps the anchor (fixed, R4.4; in an RFQ it may only fall,
R12.6), the target of every offer we made and the supplier's C after every reply (one entry per
reply, so a hold shows as a zero step).

  curve        our k-th offer closes 1 - (1 - k/H)^1.6 of the gap from the anchor to their C (R5.1)
  reciprocity  they moved more than MOVE_TOL of C: our step = max(min(planned, 0.5 x theirs), MIN_STEP
               of C) (R5.2); "planned" is at least BREAK_SHARE of the gap left (R12.5)
  deadlock     they did not move: hold ONCE, then one real step - at least BREAK_SHARE of the gap
               left and MIN_STEP of C (R5.3). Never two holds in a row, never a token step
  still moving their offer meets our target but they conceded more than MIN_STEP of C last round
               with more than 3 rounds left: target = their C - 0.5 x their step (R5.4)
  caps         never above CEILING x their C (R12.5), never above 0.995 x the alternative's C; in an
               RFQ at most 0.99 x the best rival's C and never below the anchor (R5.5)
"""

import math
from dataclasses import dataclass, field

MOVE_TOL = 0.001  # R5.2: a move under 0.1 % of C is no move
MIN_STEP = 0.004  # R5.2/R5.3: our smallest visible step, 0.4 % of C
RECIPROCITY = 0.5  # R5.2: we move by at most half of what they moved
BREAK_SHARE = 0.15  # R5.3/R12.5: a real step is at least 15 % of the gap left
CEILING = 0.997  # R12.5: never above 0.997 x their C
ALT_CAP = 0.995  # R5.5
RIVAL_CAP = 0.99  # R5.5


def curve(k, horizon):
    """Share of the gap conceded by our k-th offer (k = 0: the anchor)."""
    return 1 - (1 - min(k, horizon) / horizon) ** 1.6


@dataclass
class Plan:
    anchor: float | None = None  # in C
    targets: list = field(default_factory=list)  # the target C of every offer we made
    their_costs: list = field(default_factory=list)  # the supplier's C after every reply
    replies: int = 0
    holds: int = 0  # our holds in a row

    def observe(self, c_theirs, replies):
        """Record the supplier's C once per reply (a hold is a zero step)."""
        if replies > self.replies:
            self.their_costs.append(c_theirs)
            self.replies = replies

    def set_anchor(self, c_anchor, rfq=False):
        """Fixed once per thread (R4.4); in an RFQ it may only fall (R12.6)."""
        if self.anchor is None:
            self.anchor = c_anchor
        elif rfq:
            self.anchor = min(self.anchor, c_anchor)
        return self.anchor

    def their_step(self):
        """How far the supplier came toward us in its last reply, in C (0 for a hold)."""
        if len(self.their_costs) < 2:
            return 0.0
        return self.their_costs[-2] - self.their_costs[-1]

    def next_target(self, c_theirs, horizon, rounds_left=99, c_alt=float("inf"), rival_best=None, rfq=False):
        """The target C of our next offer and why: (target, info). Does not record it - `commit` does."""
        anchor = self.anchor if self.anchor is not None else c_theirs
        k = len(self.targets)
        planned = anchor + curve(k, horizon) * (c_theirs - anchor)
        step = self.their_step()
        moved = step > MOVE_TOL * c_theirs
        info = {"k": k, "their_step": step, "moved": moved, "kind": "anchor" if not k else None, "ours": None}
        if not k:
            target = planned
        else:
            prev = self.targets[-1]
            gap_left = max(0.0, c_theirs - prev)
            visible = MIN_STEP * c_theirs
            planned_step = max(planned - prev, BREAK_SHARE * gap_left)
            if moved:
                ours = max(min(planned_step, RECIPROCITY * step), visible)
                info["kind"] = "reciprocal"
            elif self.holds >= 1:
                ours = max(BREAK_SHARE * gap_left, visible)
                info["kind"] = "deadlock breaker"
            else:
                ours, info["kind"] = 0.0, "hold"
            target = prev + ours
            info["ours"] = ours
        info["still_moving"] = step > MIN_STEP * c_theirs
        if info["still_moving"] and target >= c_theirs and rounds_left > 3:
            # R5.4: still moving means ask again - but never for more than we last offered: going back
            # behind our own last offer reads as a retreat (judgement call, DESIGN_NOTES)
            target = max(c_theirs - 0.5 * step, self.targets[-1] if self.targets else -math.inf)
            info["kind"] = "still moving"
        target = min(target, CEILING * c_theirs, ALT_CAP * c_alt)
        if rfq and rival_best is not None:
            target = max(anchor, min(target, RIVAL_CAP * rival_best))
        return target, info

    def breaker(self, c_theirs):
        """The deadlock-breaking target (R5.3), when a hold would only repeat our last sheets (R13.7)."""
        prev = self.targets[-1] if self.targets else (self.anchor or c_theirs)
        ours = max(BREAK_SHARE * max(0.0, c_theirs - prev), MIN_STEP * c_theirs)
        return min(prev + ours, CEILING * c_theirs)

    def commit(self, target):
        """Record an offer we sent at `target`; a target equal to the last one is a hold."""
        hold = bool(self.targets) and target <= self.targets[-1] + 1e-6
        self.holds = self.holds + 1 if hold else 0
        self.targets.append(target)

    for inc in ("EXW", "FCA", "DAP"):
        if not _num(freight.get(inc)):
            freight[inc] = 0.0 if inc == "DAP" else max([x for x in freight.values() if _num(x)] or [0.0])
            w.append(f"freight for {inc} missing: {freight[inc]}")
    b["freight_eur_per_unit"] = freight
    if not isinstance(b.get("index_paths"), dict):
        b["index_paths"] = {}
    musts = []
    for m in b.get("must_haves") or []:
        if isinstance(m, dict) and m.get("field") in TERM_FIELDS and m.get("op") in OPS and "value" in m:
            musts.append(m)
        else:
            w.append(f"must-have {m!r} names no real field or operator: ignored")
    b["must_haves"] = musts
    alt = b.get("alternative") if isinstance(b.get("alternative"), dict) else {}
    if alt.get("kind") not in ("quote", "current_contract", "none"):
        w.append(f"alternative kind {alt.get('kind')!r}: treated as none")
        alt = {"kind": "none", "ref": None, "terms": {}}
    if alt.get("kind") != "none" and not _num((alt.get("terms") or {}).get("unit_price")):
        w.append("alternative without a price: treated as none")
        alt = {"kind": "none", "ref": None, "terms": {}}
    b["alternative"] = alt
    for msg in w:
        log.info("%s case check: %s", c.get("case_id"), msg)
    return c, w


def c_alternative(case):
    alt = case["buyer"].get("alternative") or {}
    if alt.get("kind") in (None, "none") or not (alt.get("terms") or {}).get("unit_price"):
        return math.inf
    try:
        return total_cost(case, alt["terms"])
    except Exception:
        return math.inf


@dataclass
class Opening:
    sid: str
    terms: dict
    std: dict
    c: float
    keeps_must_haves: bool
    estimate: est_mod.Estimate
    levers: list = field(default_factory=list)
    best_levers: dict = field(default_factory=dict)
    uncovered_units: float = 0.0
    coverage_fix: dict = field(default_factory=dict)  # {field: option} that closes the gap and lowers C
    coverage_saving: float = 0.0
    anchor: float | None = None  # price
    anchor_c: float | None = None
    floor: float | None = None


@dataclass
class Prep:
    case: dict
    warnings: list
    goal: str
    row: dict
    type_levers: list
    horizon: int
    c_alt: float
    openings: dict
    c_open: float
    clock: CaseClock

    def keeps_must_haves(self, terms, std=None):
        return must_haves_ok(self.case, terms, std)


def opening_terms(events):
    """The supplier's opening sheet from its first e-mail (term sheets, else the structured `terms`)."""
    for m in events or []:
        if m.get("from") == "buyer":
            continue
        sheets = m.get("term_sheets") or []
        if sheets and sheets[0].get("terms"):
            return sheets[0]["terms"]
        if m.get("terms"):
            return m["terms"]
    return {}


def anchor_price(case, ctx, their_price, best_quote, combo):
    """R4.1 + R4.2 + R13.12: the lowest of the goal's cut off the best quote, the current price (no
    increase at all in a price increase / raw material case), the fair price (should-cost / (1 -
    margin)) - lifted to the credibility limits: at most 25 % under its price, never under its full
    cost x 1.01, never under the price at which C stops falling."""
    b, row = case["buyer"], playbook.row(case)
    cands = [best_quote * (1 - playbook.anchor_cut(case))]
    current = b.get("current_unit_price")
    if case.get("type") in ("price_increase", "raw_material") and current and current < their_price:
        cands.append(current)
    est = ctx.est
    if est and est.point and est.source in ("should-cost", "breakdown"):
        margin = (b.get("sustainable_margin_pct") or 0) / 100 if row["fair"] is None else row["fair"]
        if margin:
            cands.append(est.point / (1 - margin))
    p = max(min(cands), their_price * (1 - playbook.MAX_ANCHOR_CUT))
    if est and est.full_cost and est.source in ("should-cost", "breakdown"):
        p = max(p, est.full_cost * 1.01)
    p = max(p, pricing.c_min_price(case, combo, ctx.std, ctx.supplier, p, their_price))
    return round(min(p, their_price), 2)


def prepare(case, threads=None, package=None, volatile=None, seconds_left=None, cash_short=None):
    """Section 0.7 for a case: with `threads` (the opening e-mails, quote PDFs read) every supplier's
    opening is priced; without them (before the session) a notional opening at the current price is
    used, so the preparation runs on the case file alone."""
    try:
        return _prepare(case, threads, package, volatile, seconds_left, cash_short or {})
    except Exception as e:  # a case file we cannot prepare must not cost the case: log and go minimal
        log.exception("%s: preparation failed (%s) - minimal defaults", (case or {}).get("case_id"), e)
        c, w = normalise(case)
        return Prep(c, [*w, f"preparation failed: {e}"], c["buyer"].get("category_goal") or "routine",
                    playbook.row(c), playbook.type_levers(c), playbook.horizon(c), c_alternative(c), {}, math.inf,
                    CaseClock(seconds_left))  # fmt: skip


def _prepare(case, threads, package, volatile, seconds_left, cash_short):
    c, warnings = normalise(case)
    b, row = c["buyer"], playbook.row(c)
    goal = b.get("category_goal") if b.get("category_goal") in playbook.PLAYBOOK else playbook.DEFAULT_GOAL
    c_alt = c_alternative(c)
    if threads:
        quotes = {sid: (opening_terms(ev), standard_terms(ev), ev) for sid, ev in threads.items()}
    else:
        price = b.get("current_unit_price") or b.get("fallback_unit_price") or 1.0
        quotes = {sid: ({"unit_price": price}, {}, []) for sid in c["suppliers"]}
    best_quote = min((q[0].get("unit_price") for q in quotes.values() if q[0].get("unit_price")), default=None)
    openings = {}
    for sid, (terms, std, events) in quotes.items():
        if not terms.get("unit_price"):
            warnings.append(f"{sid} quotes no price")
            continue
        est = est_mod.estimate(c, package, events, terms, cash_short=cash_short.get(sid, False), market_low=best_quote)
        full = complete(c, terms, std)
        ctx = Ctx(c, std, est, full, row, volatile)
        cost = ctx.c(full)
        op = Opening(sid, full, std, cost, must_haves_ok(c, full, std), est)
        sup = ctx.supplier
        op.levers = levers.lever_table(c, full, std, sup)
        op.best_levers = levers.best_levers(c, full, std, sup)
        op.uncovered_units = uncovered_units(c, full, std)
        base = {k: v for k, v in repair(c, full, std).items() if k != "unit_price"}
        # whether covering the need pays depends on the price we get for it (P08: not at its price,
        # below the fallback at ours) - so coverage is judged at our anchor
        first = anchor_price(c, ctx, full["unit_price"], best_quote or full["unit_price"], base)
        fixed = cover(ctx, base, first)
        op.coverage_fix = {f: fixed[f] for f in COVERAGE if f in fixed and fixed.get(f) != base.get(f)}
        combo = {**base, **op.coverage_fix}
        if op.coverage_fix:
            op.coverage_saving = ctx.c({**base, "unit_price": first}) - ctx.c({**combo, "unit_price": first})
        op.anchor = anchor_price(c, ctx, full["unit_price"], best_quote or full["unit_price"], combo)
        op.anchor_c = ctx.c({**combo, "unit_price": op.anchor})
        op.floor = round(floor(ctx), 2)
        openings[sid] = op
    valid = [o.c for o in openings.values() if o.keeps_must_haves]
    return Prep(c, warnings, goal, row, playbook.type_levers(c), playbook.horizon(c), c_alt, openings,
                min(valid, default=math.inf), CaseClock(seconds_left))  # fmt: skip


def summary(prep):
    """One line per supplier for the log."""
    out = [f"{prep.case['case_id']} {prep.case.get('type')}/{prep.goal}: C_alt "
           + (f"{prep.c_alt:,.0f}" if math.isfinite(prep.c_alt) else "none")]  # fmt: skip
    for o in prep.openings.values():
        lv = ", ".join(f"{f}->{levers.label(r['option'])} {-r['delta_eur']:,.0f}" for f, r in o.best_levers.items())
        out.append(
            f"  {o.sid}: C {o.c:,.0f} (price {o.terms['unit_price']}, "
            f"must-haves {'ok' if o.keeps_must_haves else 'BROKEN'})"
            f", uncovered {o.uncovered_units:,.0f} units, coverage {o.coverage_fix or '-'}, anchor {o.anchor}"
            f", floor {o.floor}, estimate {o.estimate.source} {o.estimate.full_cost}; levers: {lv or '-'}"
        )
    return "\n".join(out)

    "withdraw_language": 0.30,
}  # fmt: skip
STALE_TOL = 0.001
WITHDRAW = re.compile(
    r"\b(withdraw\w*|end (?:our|the|these) (?:talks|negotiation|discussion)s?|"
    r"no further (?:concession|movement|room)s?|"
    r"cannot go (?:any )?(?:lower|further)|our last word|last offer|look elsewhere|terminate|break off|"
    r"not continue|step back from)\b",
    re.I,
)
POSITIVE = re.compile(
    r"\b(happy|pleased|glad|appreciate\w*|fair point|thank\w*|value|welcome|good cooperation)\b", re.I
)
NEGATIVE = re.compile(
    r"\b(disappoint\w*|unacceptable|cannot accept|regret\w*|insult\w*|surpris\w*|frustrat\w*|not acceptable|"
    r"no reciprocal|final)\b",
    re.I,
)
RELATIONSHIP = re.compile(
    r"\b(generations?|family|long-standing|partnership|our foundry|regional partners|loyal\w*|years of)\b", re.I
)
DRIVER_VERB = re.compile(
    r"(?P<name>[\w-]+(?: [\w-]+){0,3}?)\s+(?:has |have )?(?P<verb>rose|risen|increased|went up|climbed|grew|"
    r"fell|dropped|decreased|went down|declined)\s+(?:by\s+)?(?P<chg>[+-]?\d+(?:[.,]\d+)?)\s?%",
    re.I,
        n += 1
    return n


def _boss(role):
    return bool(role) and any(w in role.lower() for w in BOSS_ROLES)


def walk_risk(mails):
    """(0..1, {signal: points}) over the whole thread, oldest mail first (R11.5)."""
    if not mails:
        return 0.0, {}
    last, prev = mails[-1], mails[:-1]
    if last.status == "walked_away":
        return 1.0, {"walked_away": 1.0}
    sig = {}
    if last.status == "final_offer":
        sig["final_offer"] = WALK_WEIGHTS["final_offer"]
    if (n := unchanged(mails)) >= 2:
        sig["price_unchanged_2_rounds"] = WALK_WEIGHTS["price_unchanged_2_rounds"]
    elif n == 1:
        sig["price_unchanged_1_round"] = WALK_WEIGHTS["price_unchanged_1_round"]
    delays = [m.delay for m in prev if m.delay is not None]
    if last.delay is not None and delays and last.delay > min(delays):
        sig["reply_delay_rising"] = WALK_WEIGHTS["reply_delay_rising"]
    valid = [m.validity for m in prev if m.validity is not None]
    if last.validity is not None and valid and last.validity < max(valid):
        sig["validity_shrinking"] = WALK_WEIGHTS["validity_shrinking"]
    if _boss(last.role) and any(m.role and not _boss(m.role) for m in prev):
        sig["escalated_to_boss"] = WALK_WEIGHTS["escalated_to_boss"]
    tones = [m.tone for m in prev if m.tone is not None]
    if last.tone is not None and tones and tones[-1] - last.tone >= 2:
        sig["tone_drop"] = WALK_WEIGHTS["tone_drop"]
    if last.withdraw:
        sig["withdraw_language"] = WALK_WEIGHTS["withdraw_language"]
    return round(min(1.0, sum(sig.values())), 2), sig


def tone_by_code(body):
    pos, neg = len(POSITIVE.findall(body or "")), len(NEGATIVE.findall(body or ""))
    return max(-2.0, min(2.0, round((pos - 2 * neg) / 2)))


def appears(value, text):
    """R11.2: a figure the model returned is real only if the e-mail has it."""
    if value is None:
        return False
    try:
        v = float(value)
    except (TypeError, ValueError):
        return False
    if not math.isfinite(v):
        return False
    forms = {f"{v:.2f}", f"{v:.1f}", f"{v:g}", f"{v:.2f}".replace(".", ","), f"{v:.1f}".replace(".", ",")}
    if v == int(v):
        forms.add(str(int(v)))
    return any(re.search(rf"(?<![\d.,-]){re.escape(f)}(?!\d|[.,]\d)", text or "") for f in forms)


